  --kiln-ink:     #171310;
  --kiln-ink-2:   #5C5245;
  --kiln-ink-3:   #6F6558;

  --kiln-ember:      #A73510;
  --kiln-ember-lift: #8F3210;
  --kiln-on-ember:   #FFF7F1;
  --kiln-ember-wash: rgb(179 63 20 / 0.10);
  --kiln-ok:         #2F7A45;

  --kiln-ring:       rgb(23 19 16 / 0.10);
