  --kiln-edge-lit:   rgb(255 255 255 / 0.70);
  --kiln-edge-shade: rgb(23 19 16 / 0.06);

  --kiln-shadow-rgb: 74 52 32;
  --kiln-elev-1: 0 1px 2px rgb(var(--kiln-shadow-rgb) / .10),
